-- OUTREPD — everything the server needs, in one paste.
--
-- Generated by joining the files in `supabase/` in the order they depend on
-- each other. Paste it into the Supabase SQL editor and run it once.
-- Re-running is safe: every object is created with `if not exists`, `or
-- replace`, or dropped first.
--
-- Regenerate with:  python tool/build_install.py
--
-- Afterwards, from the app folder:
--
--   flutter test test/ladder_server_test.dart  --dart-define=...   (485 cases)
--   flutter test test/duel_server_test.dart    --dart-define=...   (a real duel)


-- ========================================================================
-- schema.sql
-- ========================================================================

-- OUTREPD — the smallest schema that makes a duel real.
--
-- Three tables. A profile is who somebody is on the ladder; a set is one
-- minute of push-ups with the evidence behind the count; a duel is two sets
-- compared. Everything else the app shows — history, the board, the accuracy
-- record — is a query over these.
--
-- Two rules run through the whole file, and both exist because the client is
-- a phone in somebody else's hands:
--
--   1. **Nobody writes their own rank.** Not the tier, not the LP, not the
--      win count. Those columns are written by `settle_duel` and by nothing
--      else. A client that could write them could type itself to the top.
--   2. **A score carries its evidence.** Every set stores what the camera
--      counted *and* what the lifter confirmed, because today the lifter has
--      the last word and one day a server may need to check. Evidence cannot
--      be added to matches that are already over, so it is stored from the
--      first row.

-- ─────────────────────────────── profiles ────────────────────────────────────

create table if not exists profiles (
  id            uuid primary key references auth.users on delete cascade,
  username      text not null unique
                check (char_length(username) between 2 and 20),
  -- Null until `set_my_username` has been called once. Every account gets
  -- exactly one rename, and this is what `set_my_username` checks to know
  -- whether that one has already been spent.
  username_changed_at timestamptz,
  -- Points into the `avatars` storage bucket. Null means the drawn initial
  -- every screen already falls back to, not a broken image.
  avatar_url    text,
  country       text,
  created_at    timestamptz not null default now(),

  -- The ladder. Seven tiers of five divisions; LP runs 0..99 inside a
  -- division. `top_tier()` in ladder.sql is the same number.
  tier_idx      int  not null default 0 check (tier_idx between 0 and 6),
  div_idx       int  not null default 0 check (div_idx  between 0 and 4),
  lp            int  not null default 0 check (lp between 0 and 99),

  -- The floor: the highest tier ever held. A tier once reached is kept, so a
  -- losing streak can cost divisions and never the tier itself.
  peak_tier_idx int  not null default 0 check (peak_tier_idx between 0 and 6),

  -- Placements. Until these are done there is no rank at all, which is the
  -- point of them.
  placements_done int not null default 0 check (placements_done between 0 and 5),
  placement_wins  int not null default 0 check (placement_wins  between 0 and 5),

  wins          int not null default 0 check (wins   >= 0),
  losses        int not null default 0 check (losses >= 0),
  win_streak    int not null default 0 check (win_streak  >= 0),
  best_streak   int not null default 0 check (best_streak >= 0),

  total_reps    int not null default 0 check (total_reps >= 0),
  best_set      int not null default 0 check (best_set   >= 0),

  -- ── what this lifter has asked for ──────────────────────────────────────
  --
  -- Preferences, not ladder state, so the guard below leaves them alone: a
  -- client may write these and only these about itself.

  -- Who may be handed this account's stored sets to race.
  challengeable text not null default 'everyone'
                check (challengeable in ('everyone', 'friends', 'nobody')),

  -- Whether to appear on the boards at all, and whether the country board is
  -- one of them. Enforced in `leaderboard()` rather than filtered on the
  -- phone, because a preference a client can skip is not a preference.
  show_on_board bool not null default true,
  show_country  bool not null default true,

  -- Which of the three things that actually happen are worth being told
  -- about. Checked by the triggers in notify.sql, so a notice somebody said
  -- they did not want is never written down in the first place.
  notify_raced          bool not null default true,
  notify_friend_request bool not null default true,
  notify_friend_ok      bool not null default true,
  notify_challenged     bool not null default true,

  updated_at    timestamptz not null default now()
);

-- For a project created before the preferences above existed.
alter table profiles add column if not exists challengeable text not null
  default 'everyone';
alter table profiles drop constraint if exists profiles_challengeable_check;
alter table profiles add constraint profiles_challengeable_check
  check (challengeable in ('everyone', 'friends', 'nobody'));
alter table profiles add column if not exists show_on_board bool not null
  default true;
alter table profiles add column if not exists show_country bool not null
  default true;
alter table profiles add column if not exists notify_raced bool not null
  default true;
alter table profiles add column if not exists notify_friend_request bool
  not null default true;
alter table profiles add column if not exists notify_friend_ok bool not null
  default true;
alter table profiles add column if not exists notify_challenged bool not null
  default true;
alter table profiles add column if not exists avatar_url text;
alter table profiles add column if not exists username_changed_at timestamptz;

comment on column profiles.lp is
  'Written by settle_duel only. The client cannot move its own rank.';

-- For a project created when the ladder had nine tiers.
--
-- `create table if not exists` above does nothing to a table that already
-- exists, so the narrower checks have to be applied by hand. Any account
-- sitting on a rung that no longer exists comes down to Master first — there
-- is nowhere else for it to be, and a row that violates its own constraint
-- cannot be written again by anything.
--
-- The guard trigger refuses writes to these columns, including this one, so
-- it is opened for the length of the transaction exactly the way settle_duel
-- does it.
do $$
begin
  perform set_config('outrepd.settling', 'on', true);
  update profiles
     set tier_idx      = least(tier_idx, 6),
         peak_tier_idx = least(peak_tier_idx, 6)
   where tier_idx > 6 or peak_tier_idx > 6;
  perform set_config('outrepd.settling', 'off', true);
end $$;

alter table profiles drop constraint if exists profiles_tier_idx_check;
alter table profiles add constraint profiles_tier_idx_check
  check (tier_idx between 0 and 6);
alter table profiles drop constraint if exists profiles_peak_tier_idx_check;
alter table profiles add constraint profiles_peak_tier_idx_check
  check (peak_tier_idx between 0 and 6);

-- The board reads this constantly, and always in the same order.
create index if not exists profiles_ladder_idx
  on profiles (tier_idx desc, div_idx desc, lp desc);

-- ──────────────────────────────── friend code ─────────────────────────────────

-- A short number that names an account the way a username does, without
-- being one. Usernames are already unique, so this is not for telling two
-- lifters apart — it is for adding one without having to hand over the name
-- shown on the ladder to do it.
create or replace function generate_friend_code()
returns text
language plpgsql
as $$
declare
  candidate text;
begin
  loop
    candidate := lpad(floor(random() * 1000000)::int::text, 6, '0');
    exit when not exists (
      select 1 from profiles where friend_code = candidate
    );
  end loop;
  return candidate;
end;
$$;

alter table profiles add column if not exists friend_code text unique;

-- Backfills any row from before this column existed, one at a time — an
-- ordinary multi-row UPDATE would hand every row the same snapshot of "codes
-- already taken" and could mint the same candidate for two rows in one go,
-- which the unique constraint would then simply refuse outright. A loop asks
-- fresh each time, the same reason settle_duel never batches a ladder change.
--
-- Guarded like the tier migration above: the guard trigger below refuses any
-- write to this column once it exists, and on a project where this has
-- already run once, it does.
do $$
declare
  r record;
begin
  perform set_config('outrepd.settling', 'on', true);
  for r in select id from profiles where friend_code is null loop
    update profiles set friend_code = generate_friend_code() where id = r.id;
  end loop;
  perform set_config('outrepd.settling', 'off', true);
end $$;

alter table profiles alter column friend_code set not null;
alter table profiles alter column friend_code set default generate_friend_code();

-- ──────────────────────────────── sets ───────────────────────────────────────

create table if not exists sets (
  id            uuid primary key default gen_random_uuid(),
  profile_id    uuid not null references profiles on delete cascade,
  created_at    timestamptz not null default now(),

  -- The two numbers, kept apart on purpose.
  --
  -- `reps_camera` is what the counter scored. `reps` is what the lifter
  -- confirmed, and it is the one that plays. Storing only the second would
  -- throw away the only measurement of the counter this project will ever
  -- have; storing only the first would mean the app had overruled somebody
  -- about their own set.
  reps          int  not null check (reps between 0 and 300),
  reps_camera   int  not null check (reps_camera between 0 and 300),

  -- How far a typical rep travelled against this lifter's own deepest, and
  -- whether the counter's three signals agreed. Both come out of the counter
  -- and both feed the LP.
  depth         real not null default 0 check (depth between 0 and 1),
  confident     bool not null default false,

  duration_ms   int  not null check (duration_ms > 0),

  -- Set when the lifter walked out mid-round. A duel that ends this way is a
  -- loss whatever the count said at the moment they left.
  gave_up       bool not null default false,

  -- When each rep landed, in milliseconds from the start of the set.
  --
  -- This is what lets an opponent's bar move at their own pace instead of
  -- their total spread evenly across the minute. Evenly is a lie — nobody is
  -- metronomic, and the last ten seconds of a minute of push-ups are nothing
  -- like the first — and racing a lie feels like racing a progress bar.
  --
  -- Small: a hundred reps is a hundred integers, a few hundred bytes. The
  -- pose recording it is read from is nine hundred kilobytes, which is why
  -- that one is not always kept and this one always is.
  rep_times     int[] not null default '{}'
                check (array_length(rep_times, 1) is null
                       or array_length(rep_times, 1) <= 300),

  -- The pose recording, when there is one. Deliberately not always: a minute
  -- of frames is about 900 KB, so the free tier holds roughly a thousand of
  -- them. Uploaded when the counter was unsure, or when the lifter offers it.
  recording_path text,

  -- Which duel consumed this set, if any. A set is faced once.
  claimed_by    uuid,

  -- Set only for a rematch: this set is not for the open pool, it is
  -- reserved for exactly this one lifter to find with `find_targeted_set`.
  -- Null is the ordinary case and means "anyone find_opponent_set matches".
  challenge_target uuid references profiles on delete set null
);

-- For a project that already has the table from an earlier paste.
alter table sets add column if not exists rep_times int[] not null default '{}';
alter table sets add column if not exists challenge_target uuid
  references profiles on delete set null;

create index if not exists sets_open_idx
  on sets (profile_id, created_at desc)
  where claimed_by is null;

-- Reps are counted when the set is stored, not when it is raced.
--
-- A set is push-ups somebody did. Counting them at settle time meant the
-- challenger's reps landed and the defender's never did — their set was raced
-- *by* somebody, and nothing ever added it to their own total.
create or replace function count_reps_of_set()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  perform set_config('outrepd.settling', 'on', true);
  update profiles set
    total_reps = total_reps + new.reps,
    best_set   = greatest(best_set, new.reps)
  where id = new.profile_id;
  perform set_config('outrepd.settling', 'off', true);
  return new;
end;
$$;

drop trigger if exists sets_count_reps on sets;
create trigger sets_count_reps
  after insert on sets
  for each row execute function count_reps_of_set();

-- ──────────────────────────────── duels ──────────────────────────────────────

create table if not exists duels (
  id            uuid primary key default gen_random_uuid(),
  created_at    timestamptz not null default now(),

  challenger    uuid not null references profiles on delete cascade,
  defender      uuid not null references profiles on delete cascade,
  challenger_set uuid not null references sets on delete cascade,
  defender_set   uuid not null references sets on delete cascade,

  -- Null on a draw, which the reps allow and the ladder has to survive.
  winner        uuid references profiles on delete set null,

  -- A friend room is a real duel and not a rung. Unranked duels are recorded
  -- and pay nothing: not LP, not the win record the ladder is built on.
  ranked        bool not null default true,

  lp_challenger int not null default 0,
  lp_defender   int not null default 0,

  check (challenger <> defender)
);

create index if not exists duels_for_profile_idx
  on duels (challenger, created_at desc);
create index if not exists duels_against_profile_idx
  on duels (defender, created_at desc);

-- ───────────────────────────── row level security ────────────────────────────

alter table profiles enable row level security;
alter table sets     enable row level security;
alter table duels    enable row level security;

-- Anyone signed in can read any profile: that is what a leaderboard is.
drop policy if exists "profiles are public to signed-in lifters" on profiles;
create policy "profiles are public to signed-in lifters"
  on profiles for select
  to authenticated
  using (true);

drop policy if exists "a lifter creates their own profile" on profiles;
create policy "a lifter creates their own profile"
  on profiles for insert
  to authenticated
  with check (auth.uid() = id);

-- The only columns a lifter may change about themselves are the ones that are
-- about them rather than about their standing. The ladder columns are locked
-- by the trigger below, because a column list in a policy cannot express
-- "these may change and those may not".
drop policy if exists "a lifter edits their own profile" on profiles;
create policy "a lifter edits their own profile"
  on profiles for update
  to authenticated
  using (auth.uid() = id)
  with check (auth.uid() = id);

create or replace function guard_ladder_columns()
returns trigger
language plpgsql
as $$
begin
  -- settle_duel runs as the definer and sets this for the length of its
  -- transaction. Anything else touching these columns is a client trying to
  -- write its own rank.
  if current_setting('outrepd.settling', true) = 'on' then
    return new;
  end if;

  if new.tier_idx        is distinct from old.tier_idx
  or new.div_idx         is distinct from old.div_idx
  or new.lp              is distinct from old.lp
  or new.peak_tier_idx   is distinct from old.peak_tier_idx
  or new.wins            is distinct from old.wins
  or new.losses          is distinct from old.losses
  or new.win_streak      is distinct from old.win_streak
  or new.best_streak     is distinct from old.best_streak
  or new.placements_done is distinct from old.placements_done
  or new.placement_wins  is distinct from old.placement_wins
  or new.total_reps      is distinct from old.total_reps
  or new.best_set        is distinct from old.best_set then
    raise exception 'rank and record are settled by the server, not the client';
  end if;

  -- A code that a lifter could rewrite is a code somebody could hand out,
  -- have declined, and then mint a fresh one to try again under. It is
  -- assigned once, the same way an id is.
  if new.friend_code is distinct from old.friend_code then
    raise exception 'friend_code is assigned by the server, not the client';
  end if;

  new.updated_at := now();
  return new;
end;
$$;

drop trigger if exists profiles_guard_ladder on profiles;
create trigger profiles_guard_ladder
  before update on profiles
  for each row execute function guard_ladder_columns();

-- A set belongs to the lifter who did it. They may write it once and read
-- their own; everyone can read a set that a duel has already joined them to.
drop policy if exists "a lifter writes their own sets" on sets;
create policy "a lifter writes their own sets"
  on sets for insert
  to authenticated
  with check (auth.uid() = profile_id);

drop policy if exists "a lifter reads their own sets" on sets;
create policy "a lifter reads their own sets"
  on sets for select
  to authenticated
  using (auth.uid() = profile_id);

-- Duels are readable by the two people in them, and by nobody else.
drop policy if exists "a lifter reads their own duels" on duels;
create policy "a lifter reads their own duels"
  on duels for select
  to authenticated
  using (auth.uid() = challenger or auth.uid() = defender);

-- Nothing inserts into duels directly. settle_duel does it, as the definer.

-- ──────────────────────────────── blocks ─────────────────────────────────────

-- Somebody you want nothing further to do with.
--
-- One row, one direction: you blocked them. It is read from both ends
-- wherever it is enforced, because blocking has to work whichever of the two
-- opens the app — but only one of you gets to undo it, and they are not told
-- it happened.
create table if not exists blocks (
  blocker    uuid not null references profiles on delete cascade,
  blocked    uuid not null references profiles on delete cascade,
  created_at timestamptz not null default now(),
  primary key (blocker, blocked),
  check (blocker <> blocked)
);

create index if not exists blocks_blocked_idx on blocks (blocked);

alter table blocks enable row level security;

-- Only the blocker sees the row. Showing it to the blocked person would
-- tell them, which is the one thing a block must not do.
drop policy if exists "a lifter reads their own blocks" on blocks;
create policy "a lifter reads their own blocks"
  on blocks for select
  to authenticated
  using (auth.uid() = blocker);

drop policy if exists "a lifter blocks in their own name" on blocks;
create policy "a lifter blocks in their own name"
  on blocks for insert
  to authenticated
  with check (auth.uid() = blocker);

drop policy if exists "a lifter unblocks their own" on blocks;
create policy "a lifter unblocks their own"
  on blocks for delete
  to authenticated
  using (auth.uid() = blocker);

-- ──────────────────────────────────── mutes ───────────────────────────────────

-- Somebody whose stored sets you would rather not be offered.
--
-- Lighter than a block: it says nothing to the friendship, the profile is
-- still visible, and they are never told. One row, one direction, checked
-- only from the muter's own side — muting somebody stops them turning up as
-- an opponent for you; it says nothing about whether your own sets still
-- turn up for them.
create table if not exists mutes (
  muter      uuid not null references profiles on delete cascade,
  muted      uuid not null references profiles on delete cascade,
  created_at timestamptz not null default now(),
  primary key (muter, muted),
  check (muter <> muted)
);

create index if not exists mutes_muted_idx on mutes (muted);

alter table mutes enable row level security;

-- Only the muter sees the row, same as a block: it must not be a way to find
-- out somebody muted you.
drop policy if exists "a lifter reads their own mutes" on mutes;
create policy "a lifter reads their own mutes"
  on mutes for select
  to authenticated
  using (auth.uid() = muter);

drop policy if exists "a lifter mutes in their own name" on mutes;
create policy "a lifter mutes in their own name"
  on mutes for insert
  to authenticated
  with check (auth.uid() = muter);

drop policy if exists "a lifter unmutes their own" on mutes;
create policy "a lifter unmutes their own"
  on mutes for delete
  to authenticated
  using (auth.uid() = muter);

-- ──────────────────────────────── reports ────────────────────────────────────

-- Somebody saying something is wrong.
--
-- Write-only from the app's side: a reporter may file one and can never read
-- the pile back, because the pile is about other people. Nothing in the app
-- reads this table at all — it is read by whoever is looking at reports, in
-- the dashboard.
create table if not exists reports (
  id          uuid primary key default gen_random_uuid(),
  reporter    uuid not null references profiles on delete cascade,
  reported    uuid references profiles on delete set null,
  created_at  timestamptz not null default now(),

  reason text not null
         check (reason in ('cheating', 'harassment', 'content',
                           'impersonation', 'other')),

  -- Optional, and capped: a free text box with no limit is a free text box
  -- somebody will paste a novel into.
  details text not null default '' check (char_length(details) <= 1000)
);

create index if not exists reports_reported_idx
  on reports (reported, created_at desc);

alter table reports enable row level security;

drop policy if exists "a lifter files their own reports" on reports;
create policy "a lifter files their own reports"
  on reports for insert
  to authenticated
  with check (auth.uid() = reporter);

-- Deliberately no select policy. Filing a report does not entitle anybody to
-- read reports, including their own — there is nothing useful in reading it
-- back, and a readable pile is one more thing to leak.

-- ──────────────────────────────── avatars ─────────────────────────────────────

-- The photo behind `profiles.avatar_url`.
--
-- Public read, because an avatar is drawn on everyone else's screen too — the
-- leaderboard, a stranger's profile, a shared card. Public storage is not
-- public data: nothing here is a photo unless a lifter chose to upload one,
-- and the path convention below is what keeps one account from overwriting
-- another's.
--
-- Path convention: `<account id>/photo`. `storage.foldername(name)` splits
-- that on `/`, so its first element is the id a write has to match.
insert into storage.buckets (id, name, public)
values ('avatars', 'avatars', true)
on conflict (id) do nothing;

drop policy if exists "avatars are public to read" on storage.objects;
create policy "avatars are public to read"
  on storage.objects for select
  using (bucket_id = 'avatars');

drop policy if exists "a lifter uploads their own avatar" on storage.objects;
create policy "a lifter uploads their own avatar"
  on storage.objects for insert
  to authenticated
  with check (
    bucket_id = 'avatars'
    and (storage.foldername(name))[1] = auth.uid()::text
  );

drop policy if exists "a lifter replaces their own avatar" on storage.objects;
create policy "a lifter replaces their own avatar"
  on storage.objects for update
  to authenticated
  using (
    bucket_id = 'avatars'
    and (storage.foldername(name))[1] = auth.uid()::text
  );

drop policy if exists "a lifter deletes their own avatar" on storage.objects;
create policy "a lifter deletes their own avatar"
  on storage.objects for delete
  to authenticated
  using (
    bucket_id = 'avatars'
    and (storage.foldername(name))[1] = auth.uid()::text
  );

-- ========================================================================
-- ladder.sql
-- ========================================================================

-- The ladder arithmetic, server side.
--
-- This is a twin of `lib/ranking.dart`, and twins drift. The app computes the
-- same numbers to show them before and after a round; the server computes them
-- to *apply* them, because a client that could apply its own LP could type
-- itself to the top of the board.
--
-- `test/ladder_vectors.json` is generated from the Dart implementation and
-- replayed against these functions (`supabase/ladder_test.sql`). If the two
-- ever disagree the test says which case and by how much — which is the only
-- way this stays honest, because nothing else in the system would notice.

-- ───────────────────────────── the shape of a rank ───────────────────────────

-- Nine tiers of five divisions. Divisions climb V → I, so a higher div_idx is
-- better, and LP runs 0..99 inside one.
create or replace function top_division() returns int
  language sql immutable as $$ select 4 $$;

-- Seven tiers, Iron to Master. It was nine: Mythic and Legend sat above
-- Master until the crest artwork settled at seven, and the app's own
-- `kTiers` is the other half of this number. They have to move together or
-- the server will hand out a rank the app cannot draw.
create or replace function top_tier() returns int
  language sql immutable as $$ select 6 $$;

-- The rung somebody is standing on, counted from the bottom, starting at 1.
create or replace function ladder_level(tier_idx int, div_idx int)
returns int
language sql immutable
as $$
  select least(greatest(tier_idx, 0), top_tier()) * (top_division() + 1)
       + least(greatest(div_idx, 0), top_division())
       + 1;
$$;

-- ───────────────────────────── what a duel pays ──────────────────────────────

-- Exactly the gap in reps, signed by who actually won. `won` and the reps
-- normally agree; they can only split when somebody walks out while still
-- ahead, which stays a loss regardless of the count at the moment of
-- quitting — a loss must never pay a gain. No tier, no form, no cap
-- otherwise: a blowout is worth exactly what it was.
create or replace function lp_for(won boolean, your_reps int, their_reps int)
returns int
language sql
immutable
as $$
  select case when won then abs(your_reps - their_reps)
              else -abs(your_reps - their_reps) end;
$$;

-- ───────────────────────── applying it to a rank ─────────────────────────────

-- Carries a change through as many promotions or demotions as it earns, and
-- holds the floor: a tier once reached cannot be lost.
create or replace function apply_lp(
  from_tier int,
  from_div int,
  from_lp int,
  delta int,
  floor_tier int
)
returns table (tier_idx int, div_idx int, lp int)
language plpgsql
immutable
as $$
declare
  t int := from_tier;
  d int := from_div;
  p int := from_lp + delta;
begin
  while p >= 100 loop
    if t >= top_tier() and d >= top_division() then
      -- Nothing above this. LP stops rather than rolling over into a tier that
      -- does not exist.
      p := 99;
      exit;
    end if;
    p := p - 100;
    if d < top_division() then
      d := d + 1;
    else
      t := t + 1;
      d := 0;
    end if;
  end loop;

  while p < 0 loop
    if d = 0 and t <= floor_tier then
      p := 0;
      exit;
    end if;
    p := p + 100;
    if d > 0 then
      d := d - 1;
    else
      t := t - 1;
      d := top_division();
    end if;
  end loop;

  return query select t, d, p;
end;
$$;

-- ───────────────────────────── where placements land ─────────────────────────

-- Wins decide it and nothing else. Margin would let somebody buy a start by
-- picking soft opponents, and five duels is far too small a sample to read
-- anything finer than "how often did they win".
create or replace function placement_rank(wins int)
returns table (tier_idx int, div_idx int, lp int)
language sql
immutable
as $$
  -- The twin of the table in `lib/ranking.dart`. Re-spaced when the ladder
  -- went from nine tiers to seven: a clean sweep used to land at Gold IV,
  -- which is the middle of seven, and placements are not meant to hand
  -- anybody the middle of the app on their first afternoon.
  select * from (values
    (0, 2, 0),  -- no wins     → Iron III
    (0, 4, 0),  -- one in five → Iron I
    (1, 2, 0),  -- two         → Bronze III
    (1, 4, 0),  -- three       → Bronze I
    (2, 2, 0),  -- four        → Silver III
    (2, 4, 0)   -- all five    → Silver I
  ) as ladder(tier_idx, div_idx, lp)
  offset least(greatest(wins, 0), 5) limit 1;
$$;

-- ========================================================================
-- social.sql
-- ========================================================================

-- OUTREPD — the people you know.
--
-- One table and four calls. A friendship is a single row rather than two
-- mirrored ones, because two rows can disagree: accept one and not the other
-- and the app has a friend who does not have you back.
--
-- The row is keyed on (requester, addressee) and read from both ends, so
-- "who asked" survives — it is the difference between an invitation waiting
-- on you and one waiting on them, and the screen has to say which.
--
-- What is deliberately NOT here:
--
--   * A friend cannot see anything they could not already see. Profiles were
--     public to signed-in lifters before this file existed; being friends
--     adds the head-to-head, which is read out of duels the two already
--     played against each other.
--   * No presence service. "Online" is `last_seen` within a few minutes,
--     written by the app when it opens. It costs one column and one update
--     instead of a socket per lifter, and the answer it gives — "around
--     recently" — is the one the screen actually needs.

-- ──────────────────────────────── last seen ──────────────────────────────────

-- When this account last had the app open.
--
-- Not guarded like the ladder columns: there is nothing to gain by lying
-- about it, and it is the one thing on a profile a client legitimately owns.
alter table profiles add column if not exists
  last_seen timestamptz not null default now();

-- ─────────────────────────────── friendships ─────────────────────────────────

create table if not exists friendships (
  requester   uuid not null references profiles on delete cascade,
  addressee   uuid not null references profiles on delete cascade,
  created_at  timestamptz not null default now(),

  -- Null while the request is still waiting. A status column would need a
  -- check constraint and could hold 'accepted' with no date; this cannot.
  accepted_at timestamptz,

  primary key (requester, addressee),

  -- Nobody is their own friend, and the ladder would have to decide what a
  -- duel against yourself pays.
  check (requester <> addressee)
);

-- Both directions get an index: every query here asks "who is this person to
-- me", and half of those arrive from the other end of the row.
create index if not exists friendships_addressee_idx
  on friendships (addressee, accepted_at);
create index if not exists friendships_requester_idx
  on friendships (requester, accepted_at);

alter table friendships enable row level security;

-- A row is visible to the two people in it and to nobody else. A friends
-- list is not public information, and who asked whom is less so.
drop policy if exists "a lifter reads their own friendships" on friendships;
create policy "a lifter reads their own friendships"
  on friendships for select
  to authenticated
  using (auth.uid() = requester or auth.uid() = addressee);

-- You may only ever create a request as yourself. The functions below are the
-- intended door, but the policy is what actually holds: a client that skips
-- them and posts straight to the table still cannot invent an invitation from
-- somebody else.
drop policy if exists "a lifter asks in their own name" on friendships;
create policy "a lifter asks in their own name"
  on friendships for insert
  to authenticated
  with check (auth.uid() = requester);

-- Only the person who was asked can accept. Accepting your own request would
-- make every friendship unilateral.
drop policy if exists "only the asked may answer" on friendships;
create policy "only the asked may answer"
  on friendships for update
  to authenticated
  using (auth.uid() = addressee)
  with check (auth.uid() = addressee);

-- Either side can end it, and either side can withdraw a request that has
-- not been answered.
drop policy if exists "either side may end it" on friendships;
create policy "either side may end it"
  on friendships for delete
  to authenticated
  using (auth.uid() = requester or auth.uid() = addressee);

-- ──────────────────────────────── asking ─────────────────────────────────────

-- Everything asking somebody shares once the target's id is known — only how
-- that id was found (by name, by code) differs between the two functions
-- below. Kept as one body so a rule about asking (blocked, already asked you,
-- already friends) is a rule in one place instead of two copies drifting
-- apart the next time either changes.
--
-- `security definer`, for one reason: it has to see a block made *against*
-- the caller, and the blocks policy deliberately shows a row only to whoever
-- made it. Every write below still names `auth.uid()` explicitly, so the
-- extra rights buy the check and nothing else.
create or replace function request_friend_with(them uuid)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  theirs friendships;
begin
  if them = auth.uid() then
    return 'that is you';
  end if;

  -- Blocked, either way round. The same answer as a name that does not
  -- exist, deliberately: telling somebody they have been blocked is the one
  -- thing a block is supposed not to do, and an error that says "blocked"
  -- tells them.
  if exists (
    select 1 from blocks b
    where (b.blocker = auth.uid() and b.blocked = them)
       or (b.blocker = them and b.blocked = auth.uid())
  ) then
    return 'no such lifter';
  end if;

  -- They already asked you. Asking back is the same thing as saying yes, and
  -- making somebody find the request screen to agree to what they just asked
  -- for is a worse app.
  --
  -- Tested with `found` rather than `theirs is not null`: on a composite,
  -- IS NOT NULL means *every* field is filled, and a pending row always has
  -- a null accepted_at — so the obvious spelling would silently miss exactly
  -- the case this branch exists for.
  select * into theirs from friendships
   where requester = them and addressee = auth.uid();
  if found then
    if theirs.accepted_at is null then
      update friendships set accepted_at = now()
       where requester = them and addressee = auth.uid();
    end if;
    return 'friends';
  end if;

  insert into friendships (requester, addressee)
  values (auth.uid(), them)
  on conflict (requester, addressee) do nothing;

  return 'asked';
end;
$$;

-- Send a friend request, by name.
--
-- By name because that is what somebody has: you know what your friend calls
-- themselves, not their uuid. Returns the state the pair ended up in, so the
-- app can tell "asked" from "you are now friends" without asking again.
create or replace function request_friend(their_name text)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  them uuid;
begin
  select id into them from profiles where username = their_name;
  if them is null then
    return 'no such lifter';
  end if;
  return request_friend_with(them);
end;
$$;

-- Send a friend request, by their #code instead of their name.
--
-- The code exists so adding somebody never requires the name shown on the
-- ladder — see the comment on the friend_code column in schema.sql. A
-- leading '#' is accepted and stripped rather than required, since the
-- client shows the code with one but the stored value never has it.
create or replace function request_friend_by_code(code text)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  them uuid;
  cleaned text := trim(leading '#' from trim(code));
begin
  select id into them from profiles where friend_code = cleaned;
  if them is null then
    return 'no such lifter';
  end if;
  return request_friend_with(them);
end;
$$;

-- Answer a request that is waiting on you.
--
-- Declining deletes the row rather than marking it: a declined request that
-- lingers is a record of a small rejection kept on a server forever, and it
-- would also stop them ever asking again.
create or replace function answer_friend(their_id uuid, accept boolean)
returns text
language plpgsql
as $$
begin
  if accept then
    update friendships set accepted_at = now()
     where requester = their_id and addressee = auth.uid()
       and accepted_at is null;
    return case when found then 'friends' else 'nothing to answer' end;
  end if;

  delete from friendships
   where requester = their_id and addressee = auth.uid()
     and accepted_at is null;
  return 'declined';
end;
$$;

-- ──────────────────────────────── reading ────────────────────────────────────

-- Everybody this account is actually friends with, and what stands between
-- them.
--
-- The head-to-head is the reason a row is worth tapping. A rank says how good
-- somebody is in general; "0W 4L against you" is a score to settle. It is
-- counted out of ranked *and* friend duels, because a duel that happened
-- happened — the ladder ignores friend rooms, a grudge does not.
--
-- Dropped first: Postgres refuses `create or replace` when a table-returning
-- function's column set changes shape (adding avatar_url did), and fails
-- with a "cannot change return type" error that names DROP as the fix.
drop function if exists my_friends();
create or replace function my_friends()
returns table (
  id uuid,
  username text,
  tier_idx int,
  div_idx int,
  lp int,
  placements_done int,
  last_seen timestamptz,
  wins_vs_you int,
  losses_vs_you int,
  avatar_url text
)
language sql
stable
as $$
  with mine as (
    select case when f.requester = auth.uid() then f.addressee
                else f.requester end as friend_id
      from friendships f
     where f.accepted_at is not null
       and (f.requester = auth.uid() or f.addressee = auth.uid())
  )
  select p.id,
         p.username,
         p.tier_idx,
         p.div_idx,
         p.lp,
         p.placements_done,
         p.last_seen,
         -- Duels are readable only by the two people in them, so this counts
         -- exactly the ones the caller was part of without needing to say so.
         coalesce(count(*) filter (where d.winner = p.id), 0)::int,
         coalesce(count(*) filter (where d.winner = auth.uid()), 0)::int,
         p.avatar_url
    from mine
    join profiles p on p.id = mine.friend_id
    left join duels d
      on (d.challenger = auth.uid() and d.defender = p.id)
      or (d.defender = auth.uid() and d.challenger = p.id)
   group by p.id, p.username, p.tier_idx, p.div_idx, p.lp,
            p.placements_done, p.last_seen, p.avatar_url
   order by p.last_seen desc;
$$;

-- Requests waiting on an answer from this account, oldest first.
create or replace function friend_requests()
returns table (
  id uuid,
  username text,
  tier_idx int,
  div_idx int,
  asked_at timestamptz
)
language sql
stable
as $$
  select p.id, p.username, p.tier_idx, p.div_idx, f.created_at
    from friendships f
    join profiles p on p.id = f.requester
   where f.addressee = auth.uid()
     and f.accepted_at is null
   order by f.created_at;
$$;

-- Usernames keep whoever's case they were typed in (see set_my_username), so
-- finding one by name is always a case-insensitive comparison. A plain index
-- on `username` cannot serve that — Postgres only uses a btree for LIKE-style
-- matching when the indexed expression matches the comparison byte-for-byte,
-- collation included. This is the expression find_lifters() below actually
-- compares against, so it is the one that keeps every search a fast prefix
-- lookup instead of a sequential scan once there are many accounts to scan.
create index if not exists profiles_username_prefix_idx
  on profiles (lower(username) text_pattern_ops);

-- Find somebody to add, by the start of their name.
--
-- Capped hard and never open-ended: this is the one call that hands back
-- people the caller has no relationship with, so it answers a specific
-- question ("is my friend on here under this name") rather than enumerating
-- the userbase. A blank query returns nothing at all.
--
-- See the comment on my_friends() above — same reason, same fix.
drop function if exists find_lifters(text, int);
create or replace function find_lifters(query text, limit_to int default 10)
returns table (
  id uuid,
  username text,
  tier_idx int,
  div_idx int,
  placements_done int,
  avatar_url text
)
language sql
stable
security definer
set search_path = public
as $$
  select p.id, p.username, p.tier_idx, p.div_idx, p.placements_done,
         p.avatar_url
    from profiles p
   where length(trim(query)) >= 2
     and p.id <> auth.uid()
     -- Same comparison as profiles_username_prefix_idx above, on purpose:
     -- ilike would read identically but plans as a sequential scan, because
     -- nothing ties it back to that index.
     and lower(p.username) like lower(trim(query)) || '%'
     -- Somebody blocked, in either direction, is simply not there. A search
     -- that still turns them up is a block that only half works.
     and not exists (
       select 1 from blocks b
       where (b.blocker = auth.uid() and b.blocked = p.id)
          or (b.blocker = p.id and b.blocked = auth.uid())
     )
   order by p.username
   limit least(greatest(limit_to, 1), 25);
$$;

-- ──────────────────────────────── blocking ───────────────────────────────────

-- Block somebody, and end whatever was between you.
--
-- The friendship goes with it. Staying friends with somebody you have just
-- blocked is a state nothing in the app could draw honestly, and it would
-- leave them on your friends list where they can see you are still there.
create or replace function block_lifter(their_id uuid)
returns text
language plpgsql
as $$
begin
  if their_id = auth.uid() then
    return 'that is you';
  end if;

  insert into blocks (blocker, blocked)
  values (auth.uid(), their_id)
  on conflict (blocker, blocked) do nothing;

  delete from friendships
   where (requester = auth.uid() and addressee = their_id)
      or (requester = their_id and addressee = auth.uid());

  return 'blocked';
end;
$$;

create or replace function unblock_lifter(their_id uuid)
returns text
language plpgsql
as $$
begin
  delete from blocks where blocker = auth.uid() and blocked = their_id;
  return 'unblocked';
end;
$$;

-- Who this account has blocked, newest first. Only ever their own list.
create or replace function my_blocks()
returns table (
  id uuid,
  username text,
  blocked_at timestamptz
)
language sql
stable
as $$
  select p.id, p.username, b.created_at
    from blocks b
    join profiles p on p.id = b.blocked
   where b.blocker = auth.uid()
   order by b.created_at desc;
$$;

-- ───────────────────────────────── muting ────────────────────────────────────

-- Mute somebody. Nothing else changes: the friendship stands, the profile
-- stays visible, and they are not told — a block is the loud version of
-- this, and this is the one for somebody you are simply tired of racing.
create or replace function mute_lifter(their_id uuid)
returns text
language plpgsql
as $$
begin
  if their_id = auth.uid() then
    return 'that is you';
  end if;

  insert into mutes (muter, muted)
  values (auth.uid(), their_id)
  on conflict (muter, muted) do nothing;

  return 'muted';
end;
$$;

create or replace function unmute_lifter(their_id uuid)
returns text
language plpgsql
as $$
begin
  delete from mutes where muter = auth.uid() and muted = their_id;
  return 'unmuted';
end;
$$;

-- Who this account has muted, newest first. Only ever their own list.
create or replace function my_mutes()
returns table (
  id uuid,
  username text,
  muted_at timestamptz
)
language sql
stable
as $$
  select p.id, p.username, m.created_at
    from mutes m
    join profiles p on p.id = m.muted
   where m.muter = auth.uid()
   order by m.created_at desc;
$$;

-- ──────────────────────────────── the board ──────────────────────────────────

-- The board, best first, with everybody who asked to be left off it left off.
--
-- A function rather than a query from the phone, because "show me on
-- leaderboards" has to hold even when the client does not feel like adding
-- the filter. Placed accounts only: a tier on an account still in placements
-- is a column with something in it, not a rank it earned.
--
-- See the comment on my_friends() above — same reason, same fix.
-- [in_tier_idx]/[in_div_idx] narrow the board to one rung of the ladder — the
-- "ranked within your tier" list, where everybody on it is already level
-- with everybody else, and lp is what is left to tell them apart.
drop function if exists leaderboard(text, int);
create or replace function leaderboard(
  in_country text default null,
  limit_to int default 100,
  in_tier_idx int default null,
  in_div_idx int default null
)
returns table (
  id uuid,
  username text,
  tier_idx int,
  div_idx int,
  lp int,
  wins int,
  losses int,
  avatar_url text
)
language sql
stable
as $$
  select p.id, p.username, p.tier_idx, p.div_idx, p.lp, p.wins, p.losses,
         p.avatar_url
    from profiles p
   where p.placements_done >= 5
     and p.show_on_board
     and (in_country is null
          or (p.country = in_country and p.show_country))
     and (in_tier_idx is null or p.tier_idx = in_tier_idx)
     and (in_div_idx is null or p.div_idx = in_div_idx)
   order by p.tier_idx desc, p.div_idx desc, p.lp desc
   limit least(greatest(limit_to, 1), 500);
$$;

-- Where an account stands on that board, counting from 1, or null when it is
-- not on one. The same rules as above, so the number and the list can never
-- disagree about who is on it.
--
-- Takes whose place to compute rather than always asking about the caller,
-- so a profile card can show somebody else's position with the exact same
-- rules `my_board_place` uses for your own.
create or replace function board_place(for_id uuid, in_country text default null)
returns int
language sql
stable
as $$
  select case
    when not exists (
      select 1 from profiles who
       where who.id = for_id
         and who.placements_done >= 5
         and who.show_on_board
         and (in_country is null
              or (who.country = in_country and who.show_country))
    ) then null
    else (
      select count(*)::int + 1
        from profiles p, profiles who
       where who.id = for_id
         and p.placements_done >= 5
         and p.show_on_board
         and (in_country is null
              or (p.country = in_country and p.show_country))
         and (p.tier_idx > who.tier_idx
           or (p.tier_idx = who.tier_idx and p.div_idx > who.div_idx)
           or (p.tier_idx = who.tier_idx and p.div_idx = who.div_idx
               and p.lp > who.lp))
    )
  end;
$$;

create or replace function my_board_place(in_country text default null)
returns int
language sql
stable
as $$
  select board_place(auth.uid(), in_country);
$$;

-- ─────────────────────────────── a lifter's card ─────────────────────────────

-- Everything a profile card needs about somebody else, in one call rather
-- than the half-dozen a screen built from parts would need to make and then
-- hope agree with each other.
--
-- `security definer`, because the head-to-head reads both sides of a duel's
-- two sets — theirs as well as yours — and a set is normally readable only
-- by the lifter who did it. Every other function here works without that
-- because none of them needed to read a stranger's set; this is the first
-- that does.
--
-- See the comment on my_friends() above — same reason, same fix.
drop function if exists lifter_profile(uuid);
create or replace function lifter_profile(their_id uuid)
returns table (
  id uuid,
  username text,
  tier_idx int,
  div_idx int,
  lp int,
  placements_done int,
  total_reps int,
  best_set int,
  wins int,
  losses int,
  win_streak int,
  global_place int,
  country text,
  country_place int,
  is_friend bool,
  wins_vs_you int,
  losses_vs_you int,
  your_best_vs_them int,
  last_duel_at timestamptz,
  last_your_reps int,
  last_their_reps int,
  avatar_url text
)
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
begin
  if their_id = me then
    raise exception 'use your own profile screen for that';
  end if;

  return query
  with h2h as (
    select
      d.created_at,
      case when d.challenger = me then cs.reps else ds.reps end as your_reps,
      case when d.challenger = me then ds.reps else cs.reps end as their_reps,
      (d.winner = me)::int      as you_won,
      (d.winner = their_id)::int as they_won
    from duels d
    join sets cs on cs.id = d.challenger_set
    join sets ds on ds.id = d.defender_set
    where (d.challenger = me and d.defender = their_id)
       or (d.challenger = their_id and d.defender = me)
  ),
  last as (
    select * from h2h order by created_at desc limit 1
  )
  select
    p.id, p.username, p.tier_idx, p.div_idx, p.lp, p.placements_done,
    p.total_reps, p.best_set, p.wins, p.losses, p.win_streak,
    board_place(p.id, null), p.country,
    case when p.country is null then null else board_place(p.id, p.country) end,
    exists (
      select 1 from friendships f
       where f.accepted_at is not null
         and ((f.requester = me and f.addressee = their_id)
           or (f.requester = their_id and f.addressee = me))
    ),
    -- wins_vs_you/losses_vs_you keep the same meaning as my_friends() above:
    -- wins_vs_you is theirs, losses_vs_you is yours. Swapping these would
    -- read as somebody's record flipped on every profile that opens on it.
    (select coalesce(sum(they_won), 0) from h2h)::int,
    (select coalesce(sum(you_won), 0) from h2h)::int,
    (select max(your_reps) from h2h),
    (select created_at from last),
    (select your_reps from last),
    (select their_reps from last),
    p.avatar_url
  from profiles p
  where p.id = their_id;
end;
$$;

-- ───────────────────────────── the public card ───────────────────────────────

-- What a share card shows, for whoever a link reaches — the landing site's
-- /u/<username> page calls this signed out, which is the one place in the
-- app that has nobody signed in to check `to authenticated` against.
--
-- `security definer` for exactly that reason. Narrower than [lifter_profile]
-- on purpose: nothing about anybody else's relationship to this account, and
-- nothing that was not already true on the card the lifter chose to share.
--
-- See the comment on my_friends() above — same reason, same fix.
drop function if exists public_lifter_card(text);
create or replace function public_lifter_card(their_username text)
returns table (
  username text,
  tier_idx int,
  div_idx int,
  lp int,
  wins int,
  losses int,
  best_set int,
  win_streak int,
  global_place int,
  country text,
  country_place int,
  avatar_url text
)
language plpgsql
security definer
set search_path = public
as $$
declare
  who profiles;
begin
  select * into who from profiles where profiles.username = their_username;
  if who is null then
    return;
  end if;

  return query
  select
    who.username, who.tier_idx, who.div_idx, who.lp, who.wins, who.losses,
    who.best_set, who.win_streak,
    board_place(who.id, null), who.country,
    case when who.country is null then null else board_place(who.id, who.country) end,
    who.avatar_url;
end;
$$;

revoke all on function request_friend_with(uuid) from public;
grant execute on function request_friend_with(uuid) to authenticated;
revoke all on function request_friend(text) from public;
grant execute on function request_friend(text) to authenticated;
revoke all on function request_friend_by_code(text) from public;
grant execute on function request_friend_by_code(text) to authenticated;
revoke all on function answer_friend(uuid, boolean) from public;
grant execute on function answer_friend(uuid, boolean) to authenticated;
revoke all on function my_friends() from public;
grant execute on function my_friends() to authenticated;
revoke all on function friend_requests() from public;
grant execute on function friend_requests() to authenticated;
revoke all on function find_lifters(text, int) from public;
grant execute on function find_lifters(text, int) to authenticated;
revoke all on function block_lifter(uuid) from public;
grant execute on function block_lifter(uuid) to authenticated;
revoke all on function unblock_lifter(uuid) from public;
grant execute on function unblock_lifter(uuid) to authenticated;
revoke all on function my_blocks() from public;
grant execute on function my_blocks() to authenticated;
revoke all on function leaderboard(text, int, int, int) from public;
grant execute on function leaderboard(text, int, int, int) to authenticated;
revoke all on function my_board_place(text) from public;
grant execute on function my_board_place(text) to authenticated;
revoke all on function board_place(uuid, text) from public;
grant execute on function board_place(uuid, text) to authenticated;
revoke all on function mute_lifter(uuid) from public;
grant execute on function mute_lifter(uuid) to authenticated;
revoke all on function unmute_lifter(uuid) from public;
grant execute on function unmute_lifter(uuid) to authenticated;
revoke all on function my_mutes() from public;
grant execute on function my_mutes() to authenticated;
revoke all on function lifter_profile(uuid) from public;
grant execute on function lifter_profile(uuid) to authenticated;
-- The one function in this file anon may call: it is what a share link is
-- for. Also granted to authenticated, since the app itself is signed in
-- when it renders your own card.
revoke all on function public_lifter_card(text) from public;
grant execute on function public_lifter_card(text) to anon, authenticated;

-- ========================================================================
-- duel.sql
-- ========================================================================

-- Finding an opponent, and settling with them.
--
-- The whole async duel is two calls: `find_opponent_set` hands you somebody
-- else's minute to race, and `settle_duel` compares yours against it and moves
-- both ranks. Nothing else writes to the ladder.
--
-- Both are `security definer`, which is what lets them write columns the
-- caller is forbidden to touch. That makes them the attack surface: every
-- argument is treated as hostile, and the caller's identity comes from
-- `auth.uid()` rather than from anything they passed in.

-- ───────────────────────────── finding somebody ──────────────────────────────

-- A stored set from somebody near your level that you have not faced.
--
-- Async on purpose: two people being free in the same minute is the hardest
-- thing to arrange in a fitness app, and it is not needed. You race their
-- minute, they find out they were raced.
create or replace function find_opponent_set(within_levels int default 6)
returns table (
  set_id uuid,
  profile_id uuid,
  username text,
  tier_idx int,
  div_idx int,
  reps int,
  rep_times int[]
)
language plpgsql
security definer
set search_path = public
as $$
declare
  me profiles;
begin
  select * into me from profiles where id = auth.uid();
  if me is null then
    raise exception 'no profile for this account';
  end if;

  return query
  select s.id, p.id, p.username, p.tier_idx, p.div_idx, s.reps, s.rep_times
  from sets s
  join profiles p on p.id = s.profile_id
  where s.claimed_by is null
    and s.profile_id <> me.id
    -- Reserved for a rematch is not offered to the open pool — the whole
    -- point of naming a challenge_target is that only they can find it, with
    -- find_targeted_set below.
    and s.challenge_target is null
    -- Near your level, measured in rungs rather than tiers: the difference
    -- between the top and the bottom of one tier is five divisions, and
    -- matching "same tier" would pair those two.
    and abs(ladder_level(p.tier_idx, p.div_idx)
          - ladder_level(me.tier_idx, me.div_idx)) <= within_levels
    -- Not somebody you have already faced. A ladder that keeps pairing the
    -- same two people is a ladder of two.
    and not exists (
      select 1 from duels d
      where (d.challenger = me.id and d.defender = p.id)
         or (d.defender = me.id and d.challenger = p.id)
    )
    -- Whoever they said may challenge them. Enforced where the pairing is
    -- decided rather than on the phone, because a preference the client can
    -- skip is a preference in name only.
    and (
      p.challengeable = 'everyone'
      or (p.challengeable = 'friends' and exists (
            select 1 from friendships f
            where f.accepted_at is not null
              and ((f.requester = me.id and f.addressee = p.id)
                or (f.addressee = me.id and f.requester = p.id))
          ))
    )
    -- A block works whichever of the two is holding the phone, so both
    -- directions are checked. Neither is told which one it was.
    and not exists (
      select 1 from blocks b
      where (b.blocker = me.id and b.blocked = p.id)
         or (b.blocker = p.id and b.blocked = me.id)
    )
    -- A mute is one-directional and only ever checked from the muter's own
    -- side: it says "stop offering me them," not "stop offering them me."
    and not exists (
      select 1 from mutes m
      where m.muter = me.id and m.muted = p.id
    )
  -- Oldest first: a set that has been waiting is the one most likely to have
  -- been forgotten about, and its owner is owed a result.
  order by s.created_at
  limit 1;
end;
$$;

-- A specific lifter's reserved set, for a rematch.
--
-- The counterpart to `find_opponent_set` above: that one hands out anybody's
-- unraced minute at random, this one hands out exactly the one minute
-- [from_id] reserved for the caller by naming them in `challenge_target`.
-- Nothing about level or "not already faced" applies — a rematch is by
-- definition the same two people again, which is the one thing the open pool
-- refuses to pair.
create or replace function find_targeted_set(from_id uuid)
returns table (
  set_id uuid,
  profile_id uuid,
  username text,
  tier_idx int,
  div_idx int,
  reps int,
  rep_times int[]
)
language plpgsql
security definer
set search_path = public
as $$
begin
  return query
  select s.id, p.id, p.username, p.tier_idx, p.div_idx, s.reps, s.rep_times
  from sets s
  join profiles p on p.id = s.profile_id
  where s.claimed_by is null
    and s.profile_id = from_id
    and s.challenge_target = auth.uid()
    -- A block still holds even over a challenge sent before it happened.
    and not exists (
      select 1 from blocks b
      where (b.blocker = auth.uid() and b.blocked = from_id)
         or (b.blocker = from_id and b.blocked = auth.uid())
    )
  order by s.created_at desc
  limit 1;
end;
$$;

-- ─────────────────────────────── placements ─────────────────────────────────

-- Where an account stands after a placement duel.
--
-- Nothing moves until the fifth one, and then the whole rank is set at once
-- from how many were won. A tier handed out after one duel is a tier decided
-- by one opponent.
-- The parameters are named `from_*` because the returned columns are called
-- `tier_idx`, `div_idx` and `lp`, and Postgres refuses a function whose
-- inputs and outputs share a name.
create or replace function place_after(
  done int, wins int, from_tier int, from_div int, from_lp int
)
returns table (tier_idx int, div_idx int, lp int)
language plpgsql
immutable
as $$
begin
  if done < 5 then
    -- Nothing moves until the fifth. The account stays exactly where it was.
    return query select from_tier, from_div, from_lp;
  else
    return query select * from placement_rank(wins);
  end if;
end;
$$;

-- ───────────────────────────── settling a duel ───────────────────────────────

-- Compares the caller's set against a stored one and moves both ranks.
--
-- The caller passes only their own set and the one they faced. Everything that
-- decides the outcome — the reps, who gave up, both tiers — is read from the
-- rows, never from arguments, because an argument is whatever the phone felt
-- like sending.
create or replace function settle_duel(
  my_set uuid,
  their_set uuid,
  ranked boolean default true
)
returns table (
  duel_id uuid,
  won boolean,
  lp_delta int,
  tier_idx int,
  div_idx int,
  lp int,
  -- The record and the placements, read back off the row this same call just
  -- wrote. The app used to be trusted to derive these locally from the same
  -- rules — win/loss, the streak, the five placement duels — and two copies
  -- of a rule is two rules. Returning them is cheaper than that ever going
  -- wrong.
  wins int,
  losses int,
  win_streak int,
  best_streak int,
  placements_done int,
  placement_wins int
)
language plpgsql
security definer
set search_path = public
as $$
declare
  mine sets;
  theirs sets;
  me profiles;
  them profiles;
  me_after profiles;
  i_won boolean;
  after record;
  their_after record;
  d_id uuid;
  is_ranked boolean := coalesce(ranked, true);
  my_placing boolean;
  their_placing boolean;
  my_delta int;
  their_delta int;
begin
  select * into mine   from sets where id = my_set    for update;
  select * into theirs from sets where id = their_set for update;

  if mine is null or theirs is null then
    raise exception 'set not found';
  end if;
  if mine.profile_id <> auth.uid() then
    raise exception 'that is not your set';
  end if;
  if mine.claimed_by is not null or theirs.claimed_by is not null then
    -- A set is faced once. Without this, replaying the same pair of ids is
    -- free LP for whoever calls it twice.
    raise exception 'one of these sets has already been played';
  end if;
  if mine.profile_id = theirs.profile_id then
    raise exception 'cannot duel yourself';
  end if;

  select * into me   from profiles where id = mine.profile_id   for update;
  select * into them from profiles where id = theirs.profile_id for update;

  -- Walking out is a loss whatever the count said at the moment you left.
  i_won := case
             when mine.gave_up   then false
             when theirs.gave_up then true
             else mine.reps >= theirs.reps
           end;

  -- The guard on profiles lets these two updates through, and only these.
  perform set_config('outrepd.settling', 'on', true);

  -- Placements move no rank, because there is not one yet. Five duels decide
  -- where an account starts and nothing is paid until they are done — which
  -- is the whole point of them, and the app says so on screen.
  my_placing    := is_ranked and me.placements_done   < 5;
  their_placing := is_ranked and them.placements_done < 5;

  if not is_ranked then
    -- A friend room is a real duel and not a rung. It moves nothing: not the
    -- ladder, not the placements, not the win record the ladder is built on.
    my_delta := 0;
    their_delta := 0;
    select me.tier_idx, me.div_idx, me.lp into after;
    select them.tier_idx, them.div_idx, them.lp into their_after;
  elsif my_placing then
    my_delta := 0;
    select * into after from place_after(
      me.placements_done + 1,
      me.placement_wins + (case when i_won then 1 else 0 end),
      me.tier_idx, me.div_idx, me.lp
    );
  else
    my_delta := lp_for(i_won, mine.reps, theirs.reps);
    select * into after from apply_lp(
      me.tier_idx, me.div_idx, me.lp, my_delta, me.peak_tier_idx
    );
  end if;

  if is_ranked and their_placing then
    their_delta := 0;
    select * into their_after from place_after(
      them.placements_done + 1,
      them.placement_wins + (case when i_won then 0 else 1 end),
      them.tier_idx, them.div_idx, them.lp
    );
  elsif is_ranked then
    their_delta := lp_for(not i_won, theirs.reps, mine.reps);
    select * into their_after from apply_lp(
      them.tier_idx, them.div_idx, them.lp, their_delta, them.peak_tier_idx
    );
  end if;

  -- Everything below writes the ladder, and an unranked duel writes none of
  -- it. It is recorded in `duels` and that is all.
  if is_ranked then

    -- Every bare column read below is qualified as `profiles.col` rather than
    -- `col`. RETURNS TABLE above declares output columns of these same names
    -- (wins, losses, win_streak, best_streak, placements_done,
    -- placement_wins), which plpgsql turns into variables of those exact
    -- names in scope for the rest of the function — so an unqualified read
    -- here is genuinely ambiguous between "the column this statement is
    -- updating" and "the output this function will return". The assignment
    -- targets (the name left of each `=`) never need this: SET's target list
    -- can only ever mean the column.
    update profiles set
      tier_idx = after.tier_idx,
      div_idx  = after.div_idx,
      lp       = after.lp,
      peak_tier_idx = greatest(peak_tier_idx, after.tier_idx),
      placements_done = least(profiles.placements_done + 1, 5),
      placement_wins  = profiles.placement_wins
                        + (case when my_placing and i_won then 1 else 0 end),
      -- A placement is a real duel and its result is a real result, so the
      -- record counts it even though the rank does not move yet.
      wins        = profiles.wins   + (case when i_won then 1 else 0 end),
      losses      = profiles.losses + (case when i_won then 0 else 1 end),
      win_streak  = case when i_won then profiles.win_streak + 1 else 0 end,
      best_streak = greatest(profiles.best_streak,
                             case when i_won then profiles.win_streak + 1 else 0 end),
      -- Reps were counted when the set was stored, by the trigger on `sets`.
      updated_at = now()
    where id = me.id;

    update profiles set
      tier_idx = their_after.tier_idx,
      div_idx  = their_after.div_idx,
      lp       = their_after.lp,
      peak_tier_idx = greatest(peak_tier_idx, their_after.tier_idx),
      placements_done = least(profiles.placements_done + 1, 5),
      placement_wins  = profiles.placement_wins
                        + (case when their_placing and not i_won then 1 else 0 end),
      wins        = profiles.wins   + (case when i_won then 0 else 1 end),
      losses      = profiles.losses + (case when i_won then 1 else 0 end),
      win_streak  = case when i_won then 0 else profiles.win_streak + 1 end,
      best_streak = greatest(profiles.best_streak,
                             case when i_won then 0 else profiles.win_streak + 1 end)
      -- Their reps were counted when their set was stored, not again here.
    where id = them.id;
  end if;

  insert into duels (
    challenger, defender, challenger_set, defender_set,
    winner, ranked, lp_challenger, lp_defender
  ) values (
    me.id, them.id, mine.id, theirs.id,
    case when i_won then me.id else them.id end,
    is_ranked, my_delta, their_delta
  ) returning id into d_id;

  update sets set claimed_by = d_id where id in (mine.id, theirs.id);

  perform set_config('outrepd.settling', 'off', true);

  -- Read back rather than tracked through the branches above: the update
  -- above may not even have run (a friend duel touches nothing), and this is
  -- correct either way — the row's current state, whatever wrote it last.
  select * into me_after from profiles where id = me.id;

  return query select d_id, i_won, my_delta,
                      after.tier_idx, after.div_idx, after.lp,
                      me_after.wins, me_after.losses, me_after.win_streak,
                      me_after.best_streak, me_after.placements_done,
                      me_after.placement_wins;
end;
$$;

revoke all on function settle_duel(uuid, uuid, boolean) from public;
grant execute on function settle_duel(uuid, uuid, boolean) to authenticated;
revoke all on function find_opponent_set(int) from public;
grant execute on function find_opponent_set(int) to authenticated;
revoke all on function find_targeted_set(uuid) from public;
grant execute on function find_targeted_set(uuid) to authenticated;

-- ========================================================================
-- notify.sql
-- ========================================================================

-- OUTREPD — telling people what happened while they were away.
--
-- This is the half of the async duel that was missing. You race somebody's
-- stored minute and see the result immediately; *they* were not there. Until
-- this file, nothing ever told them — their set was raced, their rank moved,
-- their record changed, and the app said nothing the next time they opened
-- it. A ladder people cannot feel themselves moving on is a ladder nobody
-- plays twice.
--
-- Written by triggers rather than by the app, for the same reason the ladder
-- is: the person being told is not the person holding the phone. A client
-- cannot be asked to notify somebody else, because a client that can write
-- into somebody else's notifications can write anything it likes there.
--
-- Nothing here notifies you about your own actions. You were present for
-- those, and the screen already said so.

create table if not exists notifications (
  id          uuid primary key default gen_random_uuid(),

  -- Who it is for.
  profile_id  uuid not null references profiles on delete cascade,
  created_at  timestamptz not null default now(),
  read_at     timestamptz,

  kind text not null
       check (kind in ('raced', 'friend_request', 'friend_accepted', 'challenged')),

  -- Who caused it. The id can go — accounts get deleted — so the name is
  -- kept beside it: a notification that has forgotten who it was about is
  -- worse than no notification.
  actor       uuid references profiles on delete set null,
  actor_name  text not null default '',

  -- Only for 'raced'. The counts are stored rather than looked up, because
  -- the sets they came from are the other half of a duel that is over, and
  -- this row has to still make sense in a year.
  duel_id     uuid references duels on delete cascade,
  you_won     bool,
  your_reps   int,
  their_reps  int
);

-- For a project that already has the table from before 'challenged' existed.
alter table notifications drop constraint if exists notifications_kind_check;
alter table notifications add constraint notifications_kind_check
  check (kind in ('raced', 'friend_request', 'friend_accepted', 'challenged'));

-- Everything reads "mine, newest first", and the badge counts the unread.
create index if not exists notifications_for_profile_idx
  on notifications (profile_id, created_at desc);
create index if not exists notifications_unread_idx
  on notifications (profile_id) where read_at is null;

alter table notifications enable row level security;

-- Yours and nobody else's. There is deliberately no insert policy: every row
-- here is written by a trigger below, and a client that could insert one
-- could tell somebody they had been beaten by anyone it liked.
drop policy if exists "a lifter reads their own notifications" on notifications;
create policy "a lifter reads their own notifications"
  on notifications for select
  to authenticated
  using (auth.uid() = profile_id);

drop policy if exists "a lifter clears their own notifications" on notifications;
create policy "a lifter clears their own notifications"
  on notifications for delete
  to authenticated
  using (auth.uid() = profile_id);

-- ──────────────────────────── being raced ────────────────────────────────────

-- The defender finds out.
--
-- `settle_duel` inserts the duel, so this fires inside it. The challenger is
-- not told: they are the one who just watched it happen.
create or replace function notify_defender()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  challenger_name text;
  mine int;
  theirs int;
begin
  if not exists (
    select 1 from profiles
     where id = new.defender and notify_raced
  ) then
    return new;
  end if;

  select username into challenger_name from profiles where id = new.challenger;
  select reps into theirs from sets where id = new.challenger_set;
  select reps into mine   from sets where id = new.defender_set;

  insert into notifications (
    profile_id, kind, actor, actor_name,
    duel_id, you_won, your_reps, their_reps
  ) values (
    new.defender, 'raced', new.challenger, coalesce(challenger_name, ''),
    new.id, new.winner = new.defender, mine, theirs
  );

  return new;
end;
$$;

drop trigger if exists duels_notify_defender on duels;
create trigger duels_notify_defender
  after insert on duels
  for each row execute function notify_defender();

-- ─────────────────────────── friend requests ─────────────────────────────────

-- Somebody asked. A request nobody is told about is a request that sits
-- unanswered forever, which is how the friends screen ends up looking broken.
create or replace function notify_friend_request()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  asker text;
begin
  -- Only a real invitation. A row that arrives already accepted came from
  -- somebody asking back, and that case is handled below.
  if new.accepted_at is not null then
    return new;
  end if;

  if not exists (
    select 1 from profiles
     where id = new.addressee and notify_friend_request
  ) then
    return new;
  end if;

  select username into asker from profiles where id = new.requester;
  insert into notifications (profile_id, kind, actor, actor_name)
  values (new.addressee, 'friend_request', new.requester, coalesce(asker, ''));
  return new;
end;
$$;

drop trigger if exists friendships_notify_request on friendships;
create trigger friendships_notify_request
  after insert on friendships
  for each row execute function notify_friend_request();

-- And they said yes.
create or replace function notify_friend_accepted()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  accepter text;
begin
  -- Only on the moment it is accepted, not on every later write to the row.
  if old.accepted_at is not null or new.accepted_at is null then
    return new;
  end if;

  if not exists (
    select 1 from profiles
     where id = new.requester and notify_friend_ok
  ) then
    return new;
  end if;

  select username into accepter from profiles where id = new.addressee;
  insert into notifications (profile_id, kind, actor, actor_name)
  values (new.requester, 'friend_accepted', new.addressee,
          coalesce(accepter, ''));
  return new;
end;
$$;

drop trigger if exists friendships_notify_accepted on friendships;
create trigger friendships_notify_accepted
  after update on friendships
  for each row execute function notify_friend_accepted();

-- ────────────────────────────── being challenged ──────────────────────────────

-- Somebody reserved a set naming this account — a rematch. Fires from `sets`
-- rather than `duels`: a challenge is not a duel yet, it is one set waiting
-- for the other half, which is exactly the moment the target has to be told.
create or replace function notify_challenged()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  challenger_name text;
begin
  if new.challenge_target is null then
    return new;
  end if;

  if not exists (
    select 1 from profiles
     where id = new.challenge_target and notify_challenged
  ) then
    return new;
  end if;

  select username into challenger_name from profiles where id = new.profile_id;
  insert into notifications (profile_id, kind, actor, actor_name)
  values (new.challenge_target, 'challenged', new.profile_id,
          coalesce(challenger_name, ''));
  return new;
end;
$$;

drop trigger if exists sets_notify_challenged on sets;
create trigger sets_notify_challenged
  after insert on sets
  for each row execute function notify_challenged();

-- ──────────────────────────────── reading ────────────────────────────────────

-- Mine, newest first.
--
-- Dropped first: Postgres refuses `create or replace` when a table-returning
-- function's column set changes shape (adding `actor` did), and fails with a
-- "cannot change return type" error that names DROP as the fix.
drop function if exists my_notifications(int);
create or replace function my_notifications(limit_to int default 50)
returns table (
  id uuid,
  kind text,
  created_at timestamptz,
  unread boolean,
  actor uuid,
  actor_name text,
  you_won boolean,
  your_reps int,
  their_reps int
)
language sql
stable
as $$
  select n.id, n.kind, n.created_at, n.read_at is null,
         n.actor, n.actor_name, n.you_won, n.your_reps, n.their_reps
    from notifications n
   where n.profile_id = auth.uid()
   order by n.created_at desc
   limit least(greatest(limit_to, 1), 200);
$$;

-- What the dot on the bell is counting.
create or replace function unread_notifications()
returns int
language sql
stable
as $$
  select count(*)::int from notifications
   where profile_id = auth.uid() and read_at is null;
$$;

-- Marks the lot as read, which is what opening the screen means.
--
-- A function rather than an update policy: the only thing anybody may change
-- about a notification is whether they have seen it, and a policy broad
-- enough to allow that is broad enough to let somebody rewrite what it says.
create or replace function read_notifications()
returns int
language plpgsql
security definer
set search_path = public
as $$
declare
  touched int;
begin
  update notifications set read_at = now()
   where profile_id = auth.uid() and read_at is null;
  get diagnostics touched = row_count;
  return touched;
end;
$$;

revoke all on function my_notifications(int) from public;
grant execute on function my_notifications(int) to authenticated;
revoke all on function unread_notifications() from public;
grant execute on function unread_notifications() to authenticated;
revoke all on function read_notifications() from public;
grant execute on function read_notifications() to authenticated;

-- ========================================================================
-- account.sql
-- ========================================================================

-- OUTREPD — the two things a person is entitled to do with their account.
--
-- Take everything with them, and leave.
--
-- Both are irreversible and both are theirs alone: every query below is
-- scoped by `auth.uid()` and nothing takes an account id as an argument,
-- because a function that deletes the account you name is a function that
-- deletes anybody's.

-- Everything the server holds about the caller, in one object.
--
-- Read here rather than assembled on the phone so the answer is the
-- database's own, and so the export and the delete agree about what "your
-- data" means — the same tables appear in both.
--
-- What is *not* in here is as much the point as what is. There are no pose
-- landmarks and no video: pose detection runs on the phone and the frames
-- never leave it, so there is nothing on any server to hand back.
create or replace function my_data()
returns jsonb
language sql
stable
as $$
  select jsonb_build_object(
    'exported_at', now(),
    'profile', (
      select to_jsonb(p) - 'id' from profiles p where p.id = auth.uid()
    ),
    'sets', coalesce((
      select jsonb_agg(to_jsonb(s) - 'profile_id' order by s.created_at)
        from sets s where s.profile_id = auth.uid()
    ), '[]'::jsonb),
    'duels', coalesce((
      select jsonb_agg(to_jsonb(d) order by d.created_at)
        from duels d
       where d.challenger = auth.uid() or d.defender = auth.uid()
    ), '[]'::jsonb),
    'friends', coalesce((
      select jsonb_agg(jsonb_build_object(
               'username', p.username,
               'since', f.accepted_at,
               'you_asked', f.requester = auth.uid()))
        from friendships f
        join profiles p
          on p.id = case when f.requester = auth.uid()
                         then f.addressee else f.requester end
       where f.requester = auth.uid() or f.addressee = auth.uid()
    ), '[]'::jsonb),
    'blocked', coalesce((
      select jsonb_agg(jsonb_build_object(
               'username', p.username, 'at', b.created_at))
        from blocks b join profiles p on p.id = b.blocked
       where b.blocker = auth.uid()
    ), '[]'::jsonb),
    'notifications', coalesce((
      select jsonb_agg(to_jsonb(n) - 'profile_id' order by n.created_at)
        from notifications n where n.profile_id = auth.uid()
    ), '[]'::jsonb),
    'reports_filed', coalesce((
      select count(*) from reports r where r.reporter = auth.uid()
    ), 0)
  );
$$;

-- What is about to be lost, for the screen that asks whether you are sure.
--
-- The same numbers the profile shows, fetched again rather than passed in:
-- a confirmation screen quoting figures the client supplied is a
-- confirmation of whatever the client felt like saying.
create or replace function my_account_summary()
returns table (
  tier_idx int,
  div_idx int,
  lp int,
  placements_done int,
  total_reps int,
  best_set int,
  friends int
)
language sql
stable
as $$
  select p.tier_idx, p.div_idx, p.lp, p.placements_done,
         p.total_reps, p.best_set,
         (select count(*)::int from friendships f
           where f.accepted_at is not null
             and (f.requester = p.id or f.addressee = p.id))
    from profiles p
   where p.id = auth.uid();
$$;

-- Delete this account and everything hanging off it.
--
-- One statement: `profiles` cascades from `auth.users`, and sets, duels,
-- friendships, blocks and notifications all cascade from `profiles`. Deleting
-- the auth user is therefore the whole of it, and doing it in one place means
-- there is no list of tables to keep in step with the schema.
--
-- Duels go too: `duels.challenger` and `duels.defender` cascade, so the
-- opponent loses the row from their history. The LP it paid them stays, since
-- that lives on their own profile.
create or replace function delete_my_account()
returns void
language plpgsql
security definer
set search_path = public, auth
as $$
begin
  if auth.uid() is null then
    raise exception 'not signed in';
  end if;
  delete from auth.users where id = auth.uid();
end;
$$;

-- ─────────────────────────────── renaming ─────────────────────────────────────

-- Whether a name is free, checked before the rename screen shows it as such.
-- Case-insensitive: "Mokhtar" and "mokhtar" reading as different accounts
-- would be a bug nobody could explain.
create or replace function username_available(name text)
returns boolean
language sql
stable
as $$
  select not exists (
    select 1 from profiles where lower(username) = lower(trim(name))
  );
$$;

-- Renames this account. Once — see username_changed_at on profiles.
--
-- The only name a lifter never actually got to choose: signing up appends a
-- few characters from the account's own id so two people typing the same
-- thing at signup never collide, which is exactly the ugly result this
-- undoes. Re-checks availability itself — the gap between the screen's own
-- check and this call is exactly long enough for somebody else to take it.
--
-- Letters and digits only, four characters minimum. A tag another lifter
-- reads off a leaderboard or types into a search box, not a display name —
-- no spaces or punctuation to type around, no length short enough to be
-- somebody else by accident.
create or replace function set_my_username(new_name text)
returns text
language plpgsql
as $$
declare
  cleaned text := trim(new_name);
begin
  if auth.uid() is null then
    return 'invalid';
  end if;

  if exists (
    select 1 from profiles
     where id = auth.uid() and username_changed_at is not null
  ) then
    return 'already_changed';
  end if;

  if char_length(cleaned) < 4 or char_length(cleaned) > 20
     or cleaned !~ '^[A-Za-z0-9]+$' then
    return 'invalid';
  end if;

  if exists (
    select 1 from profiles
     where lower(username) = lower(cleaned) and id <> auth.uid()
  ) then
    return 'taken';
  end if;

  update profiles
     set username = cleaned, username_changed_at = now()
   where id = auth.uid();
  return 'ok';
end;
$$;

revoke all on function my_data() from public;
grant execute on function my_data() to authenticated;
revoke all on function my_account_summary() from public;
grant execute on function my_account_summary() to authenticated;
revoke all on function delete_my_account() from public;
grant execute on function delete_my_account() to authenticated;
revoke all on function username_available(text) from public;
grant execute on function username_available(text) to authenticated;
revoke all on function set_my_username(text) from public;
grant execute on function set_my_username(text) to authenticated;
